<script setup lang="ts">import { computed } from 'vue'; import { useRoute } from 'vue-router'; import { useAppStore } from '@/stores/app'; import ProjectTabs from '@/components/project/ProjectTabs.vue'; const route=useRoute(); const app=useAppStore(); const project=computed(()=>app.projects.find(p=>p.id===route.params.id))</script>
<template><div class="page project-page" v-if="project"><header class="project-header"><div class="project-icon large" :style="{background:project.color}">{{project.key[0]}}</div><div><p class="eyebrow">{{project.key}} project</p><h1>{{project.name}}</h1><p>{{project.description}}</p></div></header><ProjectTabs :project-id="project.id"/><RouterView :project="project"/></div><div v-else class="page"><div class="empty-state"><h2>Project not found</h2><RouterLink class="btn" to="/projects">Back to projects</RouterLink></div></div></template>
